('93466065-f18c-5b2b-906c-d170acc93233','faf7e45f-7b83-5dec-afd4-8bd8aac0812a',1,null,null,'spoken & written','a medical condition that makes you very unhappy and anxious and often prevents you from living a normal life','[ countable, uncountable ]',null,'افسردگی، رکود (اقتصادی)؛ فرونشست (زمین)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"women who suffer from post-natal depression (= that sometimes happens after the birth of a baby )","translation":"زنانی که از افسردگی پس از زایمان رنج می برند (= که گاهی بعد از تولد نوزاد اتفاق می افتد)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755718.mp3"},{"sentence":"Lucy’s mood was one of deep depression .","translation":"خلق و خوی لوسی افسردگی عمیق بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136368.mp3"}]'::jsonb,2),
