('d8675679-9ac2-5daa-a375-e3d2cbe4383c','faf7e45f-7b83-5dec-afd4-8bd8aac0812a',3,null,null,'spoken & written','a long period during which there is very little business activity and a lot of people do not have jobs','[ countable, uncountable ]',null,'دوره ای طولانی که در آن فعالیت تجاری بسیار کم است و افراد زیادی شغل ندارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the devastating effects of economic depression","translation":"اثرات مخرب رکود اقتصادی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136379.mp3"}]'::jsonb,1),
('c105be39-d434-5b2c-9f64-bd32a70b8ac1','faf7e45f-7b83-5dec-afd4-8bd8aac0812a',4,null,null,'spoken & written','a part of a surface that is lower than the other parts','[ countable ]',null,'قسمتی از سطح که پایین تر از سایر قسمت ها است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"depressions in the ground","translation":"فرورفتگی در زمین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001136393.mp3"}]'::jsonb,1),
