('36371b6e-997b-5244-a18c-e21f21caaff7','947dbe12-d72f-5ca9-8258-9a82a620c529',1,'building','ساختمان','spoken & written','the solid layer of cement , bricks , stones etc that is put under a building to support it','[ countable ]',null,'شالوده، پایه (ساختمان)؛ بنیاد (سازمان)؛ پایه (اندیشه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It took the builders three weeks to lay the foundations .","translation":"سه هفته طول کشید تا سازندگان پایه ها را بنا کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001275899.mp3"},{"sentence":"The earthquake shook the foundations of the house.","translation":"زمین لرزه پایه های خانه را تکان داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001699777.mp3"}]'::jsonb,2),
('55485f49-d88e-5f21-ab28-a912d95af373','947dbe12-d72f-5ca9-8258-9a82a620c529',2,'basic idea','ایده اولیه','spoken & written','a basic idea, principle , situation etc that something develops from','[ countable ]',null,'یک ایده اساسی، اصل، موقعیت و غیره که چیزی از آن ایجاد می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"All theories should be built on a foundation of factual knowledge.","translation":"همه نظریه ها باید بر پایه دانش واقعی بنا شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001699785.mp3"},{"sentence":"The course gives students a solid foundation in the basics of computing.","translation":"این دوره به دانش آموزان پایه ای محکم در مبانی محاسبات می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001699786.mp3"}]'::jsonb,2),
('0163c278-5436-5df7-b805-df8f345060c3','947dbe12-d72f-5ca9-8258-9a82a620c529',3,'organization','سازمان','spoken & written','an organization that gives or collects money to be used for special purposes , especially for charity or for medical research','[ countable ]',null,'سازمانی که پول می دهد یا جمع آوری می کند تا برای اهداف خاص، به ویژه برای امور خیریه یا تحقیقات پزشکی استفاده شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the British Heart Foundation","translation":"بنیاد قلب بریتانیا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001275921.mp3"}]'::jsonb,1),
('657846cf-3b4b-5aa3-8468-dd01a9e0fd7f','947dbe12-d72f-5ca9-8258-9a82a620c529',4,'establishment','استقرار','spoken & written','the establishment of an organization, business, school etc','[ uncountable ]',null,'ایجاد یک سازمان، تجارت، مدرسه و غیره',array['founding']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The school has served the community since its foundation in 1835.","translation":"این مدرسه از زمان تأسیس خود در سال 1835 به جامعه خدمت کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001275927.mp3"}]'::jsonb,1),
