('1fee6f48-40ca-5a69-b350-276e469689fb','b777a907-ddd0-5bcf-92c2-eff1de710ea0',1,null,null,'spoken & written','a job that needs a high level of education and training','[ countable ]',null,'حرفه، پیشه (متخصص)؛ حرفه (تواضع)؛ حرفه (اجرا)','{}'::text[],'{}'::text[],array['the legal profession He followed his father into the legal profession.','the medical profession The medical profession is still divided about the main cause of heart attacks.','the teaching profession There are not enough physicists entering the teaching profession.','the accountancy/accounting profession Many economics graduates enter the accountancy profession.','the nursing profession Mary had retired from the nursing profession.','the caring professions (= ones that involve looking after people ) A high proportion of people in the caring professions are women.','enter/go into/join a profession Hugh intended to enter the medical profession.','leave a profession Why do you want to leave the profession?','a member of a profession Some members of the medical profession supported the use of these drugs.','reach/be at the top of your profession He was a very highly respected man, at the top of his profession.']::text[],'[{"sentence":"members of the teaching profession","translation":"اعضای حرفه معلمی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561583.mp3"},{"sentence":"Some students enter other professions such as arts administration.","translation":"برخی از دانش آموزان وارد مشاغل دیگری مانند مدیریت هنری می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561586.mp3"},{"sentence":"people who work in the professions (= doctors, lawyers etc )","translation":"افرادی که در این حرفه ها کار می کنند (= پزشکان، وکلا و غیره)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561587.mp3"},{"sentence":"Johnson was a barrister by profession.","translation":"جانسون حرفه ای یک وکیل دادگستری بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561592.mp3"},{"sentence":"nurses, social workers, and other people in the caring professions (= ones that involve looking after people )","translation":"پرستاران، مددکاران اجتماعی و سایر افراد در حرفه های مراقبت (= مشاغلی که شامل مراقبت از افراد می شود)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561596.mp3"}]'::jsonb,5),
('7556fb6e-5b67-5d7d-9297-c1da9522c6c2','b777a907-ddd0-5bcf-92c2-eff1de710ea0',2,null,null,'spoken & written','all the people who work in a particular profession','[ singular ]',null,'همه افرادی که در یک حرفه خاص کار می کنند','{}'::text[],'{}'::text[],array['the legal profession He followed his father into the legal profession.','the medical profession The medical profession is still divided about the main cause of heart attacks.','the teaching profession There are not enough physicists entering the teaching profession.','the accountancy/accounting profession Many economics graduates enter the accountancy profession.','the nursing profession Mary had retired from the nursing profession.','the caring professions (= ones that involve looking after people ) A high proportion of people in the caring professions are women.','enter/go into/join a profession Hugh intended to enter the medical profession.','leave a profession Why do you want to leave the profession?','a member of a profession Some members of the medical profession supported the use of these drugs.','reach/be at the top of your profession He was a very highly respected man, at the top of his profession.']::text[],'[{"sentence":"the medical profession","translation":"حرفه پزشکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000298342.mp3"},{"sentence":"Our profession has been keen to use new technology.","translation":"حرفه ما مشتاق استفاده از فناوری جدید بوده است.","audio_url":null},{"sentence":"Our profession have been keen to use new technology.","translation":"حرفه ما مشتاق استفاده از فناوری جدید بوده است.","audio_url":null}]'::jsonb,3),
