('7dd9f7a6-99be-5acb-a431-573b54fc9d5e','a1c80567-f292-5014-a908-10fab34ed9dd',1,'part of something','بخشی از چیزی','spoken & written','a part of a number or an amount, considered in relation to the whole','[ countable usually singular ]',null,'نسبت، تناسب؛ سهم (جزء)؛ نسبت (مقدار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The proportion of women graduates has increased in recent years.","translation":"نسبت زنان فارغ التحصیل در سال های اخیر افزایش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302771.mp3"},{"sentence":"Every parent is asked to contribute a proportion of the total cost.","translation":"از هر والدین خواسته می شود که نسبتی از کل هزینه را مشارکت دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569328.mp3"},{"sentence":"The decision affects a significant proportion of the population.","translation":"این تصمیم بر بخش قابل توجهی از جمعیت تأثیر می گذارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569331.mp3"},{"sentence":"Although the majority of offenders are men, a small proportion – about five percent – are women.","translation":"اگرچه اکثر مجرمان را مردان تشکیل می دهند، اما بخش کوچکی - حدود پنج درصد - زن هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020190.mp3"},{"sentence":"A small proportion disagrees .","translation":"بخش کوچکی مخالف است.","audio_url":null},{"sentence":"A small proportion disagree .","translation":"تعداد کمی مخالف هستند.","audio_url":null}]'::jsonb,6),
('ffda6a27-9d98-5455-99f2-d7ed584d845b','a1c80567-f292-5014-a908-10fab34ed9dd',2,'relationship','رابطه','spoken & written','the relationship between two things in size , amount, importance etc','[ countable, uncountable ]',null,'رابطه بین دو چیز در اندازه، مقدار، اهمیت و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"What’s the proportion of boys to girls in your class?","translation":"نسبت پسر به دختر در کلاس شما چقدر است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302786.mp3"},{"sentence":"The rewards you get in this job are in direct proportion to the effort you put in.","translation":"پاداش هایی که در این شغل می گیرید با تلاشی که انجام می دهید نسبت مستقیم دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569342.mp3"}]'::jsonb,2),
('80856e9b-dc51-52fb-b3ba-79cc1fc6a91c','a1c80567-f292-5014-a908-10fab34ed9dd',3,'correct scale','مقیاس صحیح','spoken & written','the correct or most suitable relationship between the size, shape , or position of the different parts of something','[ uncountable ]',null,'درست یا مناسب ترین رابطه بین اندازه، شکل یا موقعیت قسمت های مختلف یک چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Builders must learn about scale and proportion.","translation":"سازندگان باید در مورد مقیاس و نسبت یاد بگیرند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302796.mp3"},{"sentence":"Reduce the drawing so that all the elements stay in proportion.","translation":"طراحی را کاهش دهید تا همه عناصر در تناسب باقی بمانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302799.mp3"},{"sentence":"Her feet are small in proportion to her height.","translation":"پاهای او به نسبت قدش کوچک است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766985.mp3"},{"sentence":"The porch is out of proportion with (= too big or too small when compared with ) the rest of the house.","translation":"ایوان با (= خیلی بزرگ یا خیلی کوچک در مقایسه با ) بقیه خانه تناسب ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302805.mp3"}]'::jsonb,4),
('f7ee423f-ecb4-58d2-ac4c-0265c07aca4b','a1c80567-f292-5014-a908-10fab34ed9dd',4,null,null,'spoken & written',null,null,'proportions','نسبت، تناسب؛ سهم (جزء)؛ نسبت (مقدار)','{}'::text[],'{}'::text[],array['enormous/massive/gigantic etc proportions The company is heading towards a disaster of enormous proportions.','epidemic proportions (= very great size, especially in a particular place ) Shoplifting has reached epidemic proportions.','epic proportions (= very great size or importance ) An argument of epic proportions had ensued.','mythic proportions (= a size or importance that seems almost unreal ) Achieving this was a feat of mythic proportions.','historic proportions (= a size or importance that only rarely happens ) We were trapped for three days by a blizzard of historic proportions.','crisis proportions (= a size that causes very serious problems ) The water shortage was reaching crisis proportions.','manageable proportions (= a size that is easy to deal with ) First, narrow the choice down to more manageable proportions.','reach epidemic etc proportions Alcohol abuse has reached epidemic proportions in this country.','grow to enormous etc proportions The fish grows to gigantic proportions.','assume epidemic etc proportions formal (= become or seem very great ) Unless you deal with it quickly, the damage may assume serious proportions.','reduce something to manageable etc proportions The disease had been reduced to negligible proportions by vaccination.']::text[],'[]'::jsonb,0),
('0790ee3f-e903-5b35-8db0-1981ae2e60ba','a1c80567-f292-5014-a908-10fab34ed9dd',5,null,null,'spoken & written',null,null,'out of (all) proportion','نسبت، تناسب؛ سهم (جزء)؛ نسبت (مقدار)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('bf6c70e1-d3ec-5da6-b7f5-e8ed83705db3','a1c80567-f292-5014-a908-10fab34ed9dd',6,null,null,'spoken & written',null,null,'keep something in proportion','نسبت، تناسب؛ سهم (جزء)؛ نسبت (مقدار)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
