('e63a41c6-aa4b-52ef-8fc9-e1a27aaa4117','14d55058-fe11-5bb2-a41e-76b55cc26e39',1,null,null,'spoken & written','quite or to a satisfactory degree , but not completely','[ +adj/adverb ]',null,'نسبتاً، تا حدی؛ معقولانه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The car is in reasonably good condition.","translation":"ماشین در وضعیت نسبتا خوبی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000485689.mp3"},{"sentence":"He’s doing reasonably well at school.","translation":"او در مدرسه خوب عمل می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000485690.mp3"}]'::jsonb,2),
