('22f27faa-0132-554a-98aa-af632fa5c912','ab997532-04bc-50fb-9b08-1e9d6b2042e1',1,null,null,'spoken & written','used to show that the people who do something are affected by their own action',null,null,'خودشان — ضمیر انعکاسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Teachers have no choice but to take measures to protect themselves.","translation":"معلمان چاره ای جز اتخاذ تدابیری برای محافظت از خود ندارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001995319.mp3"},{"sentence":"Our neighbours have just bought themselves a jacuzzi.","translation":"همسایه های ما به تازگی برای خود جکوزی خریده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000594293.mp3"},{"sentence":"The kids seem very pleased with themselves.","translation":"بچه ها خیلی از خودشان راضی به نظر می رسند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000594292.mp3"}]'::jsonb,3),
('1e06b04c-53dc-547b-828c-baab4f199f37','ab997532-04bc-50fb-9b08-1e9d6b2042e1',2,null,null,'spoken & written','used to emphasize the pronoun ‘they’, a plural noun etc',null,null,'برای تأکید بر ضمیر «آنها»، یک اسم جمع و غیره استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Doctors themselves are the first to admit the treatment has side effects.","translation":"خود پزشکان اولین کسانی هستند که اعتراف کردند که این درمان دارای عوارض جانبی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000594297.mp3"}]'::jsonb,1),
('e1e75fa1-564d-5bd9-af7d-17ecee7339db','ab997532-04bc-50fb-9b08-1e9d6b2042e1',3,null,null,'spoken & written','used after words like ‘everyone’, ‘anyone’, ‘no one’ etc when you talk about someone already mentioned and you do not know what sex they are or it is not important. Many teachers think this is not correct English',null,null,'بعد از کلماتی مانند «همه»، «همه»، «هیچ‌کس» و غیره وقتی در مورد شخصی صحبت می‌کنید و نمی‌دانید جنسیت او چیست یا مهم نیست. بسیاری از معلمان فکر می کنند که این انگلیسی صحیح نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Someone told me they’d actually seen the accident happen themselves.","translation":"یکی به من گفت که واقعاً تصادف را خودشان دیده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000594301.mp3"}]'::jsonb,1),
