('e59b84cd-9397-5060-8a31-ff1476cca391','8c1c6d43-b813-57bd-b849-384152918ef6',1,null,null,'spoken & written','in every part of a particular area, place etc',null,null,'در سراسرِ، در تمامِ؛ در سراسر (مکان)؛ تمام‌طول','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a large organization with offices throughout the world","translation":"یک سازمان بزرگ با دفاتر در سراسر جهان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000568054.mp3"},{"sentence":"The disease spread rapidly throughout Europe.","translation":"این بیماری به سرعت در سراسر اروپا گسترش یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591671.mp3"},{"sentence":"The house is in excellent condition, with fitted carpets throughout.","translation":"خانه در شرایط بسیار عالی با فرش های نصب شده در سراسر.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841806.mp3"}]'::jsonb,3),
('6ba1bf33-b816-5a01-a7c3-0deb89d9de09','8c1c6d43-b813-57bd-b849-384152918ef6',2,null,null,'spoken & written','during all of a particular period , from the beginning to the end',null,null,'در تمام یک دوره خاص، از ابتدا تا انتها','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We are open every weekend throughout the year.","translation":"ما هر آخر هفته در طول سال باز هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591672.mp3"},{"sentence":"He was involved in politics throughout his life.","translation":"او در طول زندگی خود درگیر سیاست بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591673.mp3"},{"sentence":"The debate continued, but Meredith remained silent throughout.","translation":"بحث ادامه یافت، اما مردیث در تمام مدت سکوت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841807.mp3"}]'::jsonb,3),
('2b7af67e-b94b-58a5-b041-36d703ef772b','5f6e5099-5a52-5219-8c9d-9a35e5c19073',1,null,null,'formal','when something changes from one form or state to another',null,null,'گذار، انتقال (حالت)؛ گذار (فرد)؛ گذار (فرد)','{}'::text[],'{}'::text[],array['smooth (= happening without any problems ) There were some difficulties in achieving a smooth transition to independence.','peaceful We all wish to see a peaceful transition.','gradual Elections will be held in the course of a gradual transition from military to civilian rule.','difficult/painful She has had to make the difficult transition from child actor to adult star.','make the transition The biggest problem will be making the transition from one system to the other.','a transition period/a period of transition The major industrial nations are in a period of transition.','a transition process/a process of transition He will deal with any problems that might arise during the transition process.']::text[],'[{"sentence":"the smooth transition from full-time work to full retirement","translation":"انتقال آرام از کار تمام وقت به بازنشستگی کامل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000554260.mp3"},{"sentence":"Making the transition from youth to adulthood can be very painful.","translation":"گذار از جوانی به بزرگسالی می تواند بسیار دردناک باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001613628.mp3"},{"sentence":"a society that is in transition (= changing )","translation":"جامعه ای که در حال گذار است (= در حال تغییر)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001839987.mp3"},{"sentence":"the period of transition to full democracy","translation":"دوره گذار به دموکراسی کامل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001613637.mp3"}]'::jsonb,4),
('48cc8692-d6cd-551d-aebb-a221b8207db6','42e396f7-8341-553a-93ad-5857e3e6bc25',1,null,null,'spoken & written','to change to a new state or start using something new',null,null,'برای تغییر به حالت جدید یا شروع استفاده از چیزی جدید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He will transition to his new role next month.","translation":"او ماه آینده به نقش جدید خود منتقل خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001633.mp3"}]'::jsonb,1),
('d22316bf-250c-55d1-9e08-7fdd64dbd6ad','6c58851a-dfff-5a5b-a042-0e04d3e3bb25',1,null,null,'spoken & written','very big, fast , powerful etc',null,null,'عظیم، بسیار بزرگ؛ فوق‌العاده (پیشرفت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Suddenly, there was a tremendous bang, and the whole station shook.","translation":"ناگهان صدای انفجار شدیدی به صدا درآمد و تمام ایستگاه به لرزه درآمد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000558192.mp3"},{"sentence":"She was making a tremendous effort to appear calm.","translation":"او تلاش زیادی می کرد تا آرام به نظر برسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001828141.mp3"},{"sentence":"She praised her husband for the tremendous support he had given her.","translation":"او از شوهرش به خاطر حمایت فوق العاده ای که از او کرده بود تمجید کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001828145.mp3"},{"sentence":"Sales have been tremendous so far this year.","translation":"فروش در سال جاری تاکنون فوق العاده بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001656326.mp3"},{"sentence":"This plan could save us a tremendous amount of money.","translation":"این طرح می تواند باعث صرفه جویی در هزینه های ما شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001656327.mp3"}]'::jsonb,5),
('b246a090-0a37-52b9-9e23-f5f8a4daad11','6c58851a-dfff-5a5b-a042-0e04d3e3bb25',2,null,null,'spoken & written','excellent',null,null,'عالی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s got a tremendous voice, hasn’t she?","translation":"او صدای فوق العاده ای دارد، اینطور نیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000558197.mp3"}]'::jsonb,1),
('c90ce1e6-d308-5db4-9b73-e63aa5d16947','d554adbd-03a7-5f6b-bf8d-b02b0faeee63',1,null,null,'spoken & written','finally, after everything else has been done or considered','[ sentence adverb ]',null,'سرانجام، در نهایت؛ نهایتاً','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ultimately, the decision rests with the child’s parents.","translation":"در نهایت، تصمیم با والدین کودک است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000543851.mp3"},{"sentence":"a long but ultimately successful campaign","translation":"یک کمپین طولانی اما در نهایت موفق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617578.mp3"}]'::jsonb,2),
('f3a40fe5-52cd-5522-9d78-077d426afed6','f800ab44-5381-582b-80f6-932b31ebeb5d',1,null,null,'spoken & written','directly under another object or covered by it',null,null,'زیرِ، زیرَ (مستقیم)؛ در زیر (چیز)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He got out of the car and looked underneath.","translation":"از ماشین پیاده شد و به زیرش نگاه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841837.mp3"},{"sentence":"It’s near where the railway goes underneath the road.","translation":"نزدیک جایی است که راه آهن به زیر جاده می رود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841838.mp3"},{"sentence":"She was wearing a smart jacket with a T-shirt underneath.","translation":"او یک ژاکت هوشمند با یک تی شرت زیر پوشیده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587786.mp3"},{"sentence":"Her blonde hair was hidden underneath a baseball cap.","translation":"موهای بلوند او زیر کلاه بیسبال پنهان شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841839.mp3"}]'::jsonb,4),
('3fad8454-eae8-5d53-ada5-73489b381058','f800ab44-5381-582b-80f6-932b31ebeb5d',2,null,null,'spoken & written','on the lower surface of something',null,null,'روی سطح زیرین چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The car was rusty underneath.","translation":"ماشین زیرش زنگ زده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002010399.mp3"},{"sentence":"A number had been painted underneath the table.","translation":"یک عدد زیر میز نقاشی شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002010400.mp3"}]'::jsonb,2),
('faf388b9-8f4c-5202-adcf-065ddc704a64','f800ab44-5381-582b-80f6-932b31ebeb5d',3,null,null,'spoken & written','used to say what someone’s character is really like when their behaviour shows a different character',null,null,'زمانی که رفتارش شخصیت دیگری را نشان می‌دهد، می‌گفتند شخصیت واقعاً چگونه است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She seems confident, but she’s really quite shy underneath.","translation":"او اعتماد به نفس به نظر می رسد، اما او واقعاً در زیر خجالتی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000546717.mp3"},{"sentence":"I think he’s a genuinely nice guy underneath it all .","translation":"من فکر می کنم که او در زیر همه چیز واقعاً یک مرد خوب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587789.mp3"}]'::jsonb,2),
('cbc2d285-ff73-59d5-be28-0010a69de569','44d7dafa-fc5f-54d8-be28-b0cb0cae48f1',1,null,null,'spoken & written',null,null,'the underneath',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('d0b66f3e-ae38-522c-bd8e-9d22bf547b4f','be534eaf-89ba-5d09-9e66-236eff08a738',1,'meaning','معنی','spoken & written','to know the meaning of what someone is telling you, or the language that they speak','[ intransitive, transitive ]',null,'فهمیدن، درک کردن؛ فهمیدن (چیزی)؛ فرض کردن (بر)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She doesn’t understand English.","translation":"او انگلیسی نمی فهمد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547031.mp3"},{"sentence":"I’m sorry, I don’t understand. Can you explain that again?","translation":"متاسفم، من نمی فهمم. میشه دوباره توضیح بدی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547032.mp3"},{"sentence":"The woman had a strong accent, and I couldn’t understand what she was saying.","translation":"زن لهجه‌ای قوی داشت و من نمی‌توانستم بفهمم چه می‌گوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587814.mp3"},{"sentence":"I’m not very good at German, but I can make myself understood.","translation":"من در آلمان خیلی خوب نیستم، اما می توانم خودم را درک کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547072.mp3"}]'::jsonb,4),
('863a3d9f-47e2-5d82-8b58-f7212ee658ac','be534eaf-89ba-5d09-9e66-236eff08a738',2,'fact/idea','واقعیت/ایده','spoken & written','to know or realize how a fact , process , situation etc works, especially through learning or experience','[ intransitive, transitive ]',null,'دانستن یا درک چگونگی عملکرد یک واقعیت، فرآیند، موقعیت و غیره، به ویژه از طریق یادگیری یا تجربه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I don’t really understand the political situation in Egypt.","translation":"من واقعاً وضعیت سیاسی مصر را درک نمی کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00928.mp3"},{"sentence":"You don’t need to understand how computers work to be able to use them.","translation":"برای اینکه بتوانید از آنها استفاده کنید، نیازی به درک نحوه کار کامپیوترها ندارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547044.mp3"},{"sentence":"How the drug works isn’t fully understood .","translation":"نحوه عملکرد دارو به طور کامل درک نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587816.mp3"},{"sentence":"I understand that this treatment may not work.","translation":"من می دانم که این درمان ممکن است کارساز نباشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092427.mp3"}]'::jsonb,4),
('f52abfa2-b6f1-5586-9603-d04a59e677db','be534eaf-89ba-5d09-9e66-236eff08a738',3,'person/feelings','شخص / احساسات','spoken & written','to realize how someone feels and why they behave the way they do, and to be sympathetic','[ intransitive, transitive ]',null,'برای درک اینکه یک نفر چه احساسی دارد و چرا اینگونه رفتار می کند و دلسوز باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My parents just don’t understand me.","translation":"پدر و مادرم فقط من را درک نمی کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547054.mp3"},{"sentence":"Just tell him how you feel – I’m sure he’ll understand.","translation":"فقط به او بگویید چه احساسی دارید - من مطمئن هستم که او متوجه خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587820.mp3"},{"sentence":"I understand how you feel, but I think you’re overreacting.","translation":"من احساس شما را درک می کنم، اما فکر می کنم شما بیش از حد واکنش نشان می دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547058.mp3"},{"sentence":"I can understand her wanting to live alone and be independent.","translation":"می توانم درک کنم که او می خواهد تنها زندگی کند و مستقل باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547061.mp3"}]'::jsonb,4),
('b3f80fb6-cde8-5c5b-9b4f-029c011200c0','be534eaf-89ba-5d09-9e66-236eff08a738',4,'believe/think','باور/فکر کن','spoken & written','to believe or think that something is true because you have heard it or read it','[ transitive ]',null,'باور کنید یا فکر کنید که چیزی درست است زیرا آن را شنیده اید یا خوانده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I understand that he was 62 when he died, ’ McLeish said.","translation":"مک لیش گفت: «می‌دانم که او 62 ساله بود که درگذشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000547067.mp3"},{"sentence":"It is understood that the Queen approves of her nephew’s romance.","translation":"مشخص است که ملکه عاشقانه برادرزاده اش را تایید می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587829.mp3"},{"sentence":"Dillons is understood to be reorganising the company’s management structure.","translation":"گفته می شود که دیلونز در حال سازماندهی مجدد ساختار مدیریت شرکت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001587832.mp3"},{"sentence":"It is understood that an agreement will be signed today.","translation":"گفته می شود امروز توافق نامه امضا خواهد شد.","audio_url":null}]'::jsonb,4),
