('e8b7f3d4-c927-58f0-bfb0-78a2f376ed36','11d7667a-2103-5b9e-92d4-5d8a41e278b4',1,null,null,'spoken & written','without a job',null,null,'بیکار، بیکار (فرد)؛ شاغل‌نبودن (حالت)',array['out of work']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an unemployed actor","translation":"یک بازیگر بیکار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001632307.mp3"},{"sentence":"I’ve only been unemployed for a few weeks.","translation":"من فقط چند هفته است که بیکار هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001632308.mp3"},{"sentence":"He’s been out of work since January.","translation":"او از ژانویه بیکار است.","audio_url":null}]'::jsonb,3),
