('02caa830-0f35-571c-adca-6b23b7d7e767','a0d47848-89fd-59e6-9fc4-40eee5e19cde',1,null,null,'spoken & written','an educational institution at the highest level , where you study for a degree',null,null,'دانشگاه، دانشگاه (مطالعه)','{}'::text[],'{}'::text[],array['go to university Her daughter was about to go to university.','be at university British English We were at university together.','study (something) at a university She studied law at Edinburgh University.','apply for university I applied for university without any real idea of what I wanted to do.','start university ( also enter university formal ) Some people take a year off before they start university.','leave university Students often find work soon after leaving university.','graduate from university (= leave after getting a degree ) She graduated from Liverpool University in 2006.','drop out of university (= leave before finishing your course ) He dropped out of university in order to join a rock band.','a university course He studied history at school and was now planning to take a university course.','a university student Thirty years ago 33% of university students were female.','a university graduate (= someone who has completed a university course ) She is a university graduate who speaks three languages.','a university lecturer/professor Her father was a university lecturer and her mother a teacher.','a university degree He was a qualified engineer with a university degree.','a university education I did not have the advantage of a university education.','a university department one of the oldest university departments in the country','the university campus (= the area of land containing the main buildings of a university ) There were violent protests on university campuses.']::text[],'[{"sentence":"She’s at Cambridge University.","translation":"او در دانشگاه کمبریج است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001673.mp3"},{"sentence":"the University of Texas","translation":"دانشگاه تگزاس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001638814.mp3"}]'::jsonb,2),
('bb3ddbbe-61ea-5d07-b54c-e1c608137b8f','177376d8-34b4-5b45-8f23-848eff9cde4d',1,null,null,'spoken & written','someone who is vulnerable can be easily harmed or hurt',null,null,'آسیب‌پذیر، ضعیف (برابر زور)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He took advantage of me when I was at my most vulnerable.","translation":"او زمانی از من سوء استفاده کرد که در آسیب پذیرترین شرایطم بودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001547125.mp3"},{"sentence":"We work mainly with the elderly and other vulnerable groups.","translation":"ما عمدتاً با سالمندان و سایر گروه های آسیب پذیر کار می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001840085.mp3"},{"sentence":"Children are most vulnerable to abuse within their own home.","translation":"کودکان بیشتر در معرض آزار و اذیت در خانه خود هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001840088.mp3"}]'::jsonb,3),
('442a6f22-2829-5f39-9857-6c7d61813f24','177376d8-34b4-5b45-8f23-848eff9cde4d',2,null,null,'spoken & written','a place, thing, or idea that is vulnerable is easy to attack or criticize',null,null,'یک مکان، چیز یا ایده ای که آسیب پذیر است به راحتی قابل حمله یا انتقاد است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The fort was vulnerable to attack from the north.","translation":"این قلعه در برابر حمله از شمال آسیب پذیر بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001840089.mp3"},{"sentence":"Their theories were badly thought out and very vulnerable to ridicule.","translation":"تئوری های آنها بد فکر شده بود و در برابر تمسخر بسیار آسیب پذیر بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001547132.mp3"}]'::jsonb,2),
('f86309bc-3dbe-5081-a2d1-8c2da24a4bfd','cfdb89e6-d314-52b7-a6d7-8ecc51b695bb',1,null,null,'spoken & written','used to emphasize a negative statement',null,null,'به‌هیچ‌وجه (تأکید نفی)',array['whatever']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He’s had no luck whatsoever.","translation":"او هیچ شانسی نداشت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517010.mp3"}]'::jsonb,1),
('d11f6e26-83ca-5d1b-9e56-c8b8fe6764ec','8f865252-fe05-5276-843d-cb182269c9f5',1,null,null,'spoken & written','existing or happening in many places or situations, or among many people',null,null,'گسترده، فراگیر؛ همه‌جاگیر (رخداد)؛ پهناور','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the widespread use of chemicals in agriculture","translation":"استفاده گسترده از مواد شیمیایی در کشاورزی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001740828.mp3"},{"sentence":"There was widespread support for the war.","translation":"حمایت گسترده ای از جنگ وجود داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001820789.mp3"},{"sentence":"The storm caused widespread damage.","translation":"طوفان خسارات گسترده ای به بار آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001820790.mp3"}]'::jsonb,3),
('fcbc8887-f163-54ff-a00a-1296b6c12608','943f783d-4ec4-5527-aaef-56afccb7bc33',1,null,null,'spoken & written','something important that you succeed in doing by your own efforts','[ countable ]',null,'دستاورد، موفقیت، کار بزرگ','{}'::text[],'{}'::text[],array['a great/fine/impressive achievement (= one that deserves to be admired ) Winning the award was a great achievement.','a remarkable/extraordinary achievement (= one that is unusual or surprising and deserves praise ) In recognition of this remarkable achievement he was awarded the OBE.','a major/important achievement Writing the book was a major achievement.','an outstanding achievement (= an extremely impressive achievement ) Eisenhower'' s outstanding achievement was to avoid war.','a considerable achievement (= one that has a large effect ) These studies represent a considerable achievement.','somebody’s crowning/supreme achievement (= the best of several impressive achievements ) Her appointment to the Paris post was the crowning achievement of her life.','something represents an achievement (= something is an achievement ) Few people realised what an enormous achievement Concorde represented.','be no mean achievement (= be difficult to achieve and therefore worth admiring ) He got the top mark in the country which is no mean achievement.','be quite an achievement (= be an impressive achievement ) Working and bringing up kids on your own is quite an achievement.']::text[],'[{"sentence":"We try to celebrate the achievements of our students.","translation":"ما سعی می کنیم از دستاوردهای دانش آموزان خود تجلیل کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000790621.mp3"},{"sentence":"His great achievement is to make all the players into a united team.","translation":"دستاورد بزرگ او این است که همه بازیکنان را به یک تیم متحد تبدیل کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645453.mp3"},{"sentence":"The test measures children’s achievements in reading, spelling, and maths.","translation":"این آزمون دستاوردهای کودکان را در خواندن، املا و ریاضی اندازه گیری می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645456.mp3"}]'::jsonb,3),
('0861e785-6782-5021-a648-d501afa19523','943f783d-4ec4-5527-aaef-56afccb7bc33',2,null,null,'spoken & written','when you achieve something or when people achieve something','[ uncountable ]',null,'وقتی به چیزی دست می یابید یا وقتی مردم به چیزی می رسند','{}'::text[],'{}'::text[],array['a great/fine/impressive achievement (= one that deserves to be admired ) Winning the award was a great achievement.','a remarkable/extraordinary achievement (= one that is unusual or surprising and deserves praise ) In recognition of this remarkable achievement he was awarded the OBE.','a major/important achievement Writing the book was a major achievement.','an outstanding achievement (= an extremely impressive achievement ) Eisenhower'' s outstanding achievement was to avoid war.','a considerable achievement (= one that has a large effect ) These studies represent a considerable achievement.','somebody’s crowning/supreme achievement (= the best of several impressive achievements ) Her appointment to the Paris post was the crowning achievement of her life.','something represents an achievement (= something is an achievement ) Few people realised what an enormous achievement Concorde represented.','be no mean achievement (= be difficult to achieve and therefore worth admiring ) He got the top mark in the country which is no mean achievement.','be quite an achievement (= be an impressive achievement ) Working and bringing up kids on your own is quite an achievement.']::text[],'[{"sentence":"Roberts is researching the effect of social class on educational achievement.","translation":"رابرتز در حال تحقیق در مورد تأثیر طبقه اجتماعی بر پیشرفت تحصیلی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000790629.mp3"},{"sentence":"As we climbed the final few metres, we felt a sense of achievement .","translation":"همانطور که چند متر آخر را بالا می رفتیم، احساس موفقیت می کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645457.mp3"}]'::jsonb,2),
('da24b011-10f9-57cd-bf92-52dd8aa32e55','c3c248b9-0faa-59bb-a991-10280e945b26',1,'admit','اعتراف','spoken & written','to admit or accept that something is true or that a situation exists',null,null,'پذیرفتن، تصدیق کردن (واقعیت یا خطا)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The family acknowledge the need for change.","translation":"خانواده نیاز به تغییر را می پذیرند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000967459.mp3"},{"sentence":"He acknowledges that when he’s tired he gets bad-tempered.","translation":"او تصدیق می کند که وقتی خسته است بداخلاق می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645486.mp3"},{"sentence":"Claire acknowledged that she was guilty.","translation":"کلر اعتراف کرد که مقصر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645487.mp3"},{"sentence":"The government must acknowledge what is happening and do something about it.","translation":"دولت باید آنچه را که اتفاق می‌افتد بپذیرد و کاری برای آن انجام دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645488.mp3"},{"sentence":"‘Maybe you are right, ’ she acknowledged.","translation":"او اذعان کرد: «شاید حق با شما باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645489.mp3"},{"sentence":"This is a fact that most smokers readily acknowledge .","translation":"این واقعیتی است که اکثر سیگاری ها به راحتی آن را تصدیق می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645490.mp3"},{"sentence":"It is acknowledged that these letters are genuine.","translation":"تصدیق می شود که این نامه ها واقعی هستند.","audio_url":null}]'::jsonb,7),
('1edf6a8b-02ab-544c-9d53-477430818011','c3c248b9-0faa-59bb-a991-10280e945b26',2,'recognize something’s importance','اهمیت چیزی را تشخیص دهد','spoken & written','if people acknowledge something, they recognize how good or important it is',null,null,'اگر مردم چیزی را تصدیق کنند، متوجه می شوند که چقدر خوب یا مهم است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Brazilian coach acknowledged the talent of his players.","translation":"سرمربی برزیلی به استعداد بازیکنانش اذعان کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00014.mp3"},{"sentence":"The film festival is acknowledged as an event of international importance.","translation":"جشنواره فیلم به عنوان یک رویداد با اهمیت بین المللی شناخته می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645498.mp3"},{"sentence":"The mill produces what is widely acknowledged to be the finest wool in the world.","translation":"این آسیاب چیزی را تولید می کند که به طور گسترده به عنوان بهترین پشم در جهان شناخته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645501.mp3"}]'::jsonb,3),
('a7d11bf1-d72c-5fba-90a6-daeb4408acda','c3c248b9-0faa-59bb-a991-10280e945b26',3,'accept somebody’s authority','اقتدار کسی را بپذیر','spoken & written','to accept that someone or something has authority over people',null,null,'پذیرش اینکه کسی یا چیزی بر مردم اقتدار دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Both defendants refused to acknowledge the authority of the court.","translation":"هر دو متهم از تصدیق اختیارات دادگاه خودداری کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000967475.mp3"},{"sentence":"Many of the poor acknowledged him as their spiritual leader.","translation":"بسیاری از فقرا او را به عنوان رهبر معنوی خود تصدیق کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645505.mp3"}]'::jsonb,2),
('3319d7e1-bdae-5e64-99ff-c22a64f78a55','c3c248b9-0faa-59bb-a991-10280e945b26',4,'thank','تشکر','spoken & written','to publicly announce that you are grateful for the help that someone has given you',null,null,'به طور عمومی اعلام کنید که از کمکی که کسی به شما کرده است سپاسگزار هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We wish to acknowledge the support of the university.","translation":"مایلیم از حمایت دانشگاه قدردانی کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000967492.mp3"}]'::jsonb,1),
('3935fb84-9e59-5022-8639-30e8c68854a1','c3c248b9-0faa-59bb-a991-10280e945b26',5,'show you notice somebody','به شما نشان می دهد که به کسی توجه کنید','spoken & written','to show someone that you have noticed them or heard what they have said',null,null,'به کسی نشان دهید که متوجه او شده اید یا آنچه را که گفته اند شنیده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tom acknowledged her presence by a brief glance.","translation":"تام با یک نگاه کوتاه حضور او را تایید کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645508.mp3"}]'::jsonb,1),
('c336eb73-78e1-53e6-8259-a7aebd85ddbd','c3c248b9-0faa-59bb-a991-10280e945b26',6,'say you have received something','بگو چیزی دریافت کرده ای','spoken & written','to let someone know that you have received something from them',null,null,'به کسی بفهمانید که چیزی از او دریافت کرده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I would be grateful if you would acknowledge receipt of this letter.","translation":"اگر دریافت این نامه را تایید کنید، سپاسگزار خواهم بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645511.mp3"}]'::jsonb,1),
('9c62757a-e413-5382-8af9-e893a89bc622','2da5b9b7-6adc-57ca-9cac-82bd5dfb56ee',1,null,null,'spoken & written','the activity or business of advertising things on television , in newspapers etc',null,null,'تبلیغات، کار تبلیغ','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"advertising aimed at 18–25 year olds","translation":"تبلیغات برای افراد 18 تا 25 ساله","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000793612.mp3"},{"sentence":"a career in advertising","translation":"حرفه ای در تبلیغات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000793613.mp3"},{"sentence":"Both candidates are spending millions on television advertising.","translation":"هر دو نامزد میلیون ها دلار برای تبلیغات تلویزیونی هزینه می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646594.mp3"},{"sentence":"a major advertising campaign","translation":"یک کمپین تبلیغاتی بزرگ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000029.mp3"},{"sentence":"the advertising slogan ‘Come alive with Pepsi’","translation":"شعار تبلیغاتی \"با پپسی زنده شو\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776573.mp3"}]'::jsonb,5),
('a698fa31-518d-5bfe-8c51-8d3def96b26d','32169ab3-483a-5abb-ad68-875633c8e5d4',1,null,null,'spoken & written','the practice or science of farming',null,null,'کشاورزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"More than 75% of the land is used for agriculture.","translation":"بیش از 75 درصد از زمین ها برای کشاورزی استفاده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001662633.mp3"}]'::jsonb,1),
('56bd77b0-d662-57ca-a0b9-a1d1bf2571e5','f927cf96-5f40-57db-a6f0-effdd2b58b0e',1,null,null,'spoken & written','an alternative idea, plan etc is different from the one you have and can be used instead','[ only before noun ]',null,'جایگزین، بدل (ایده، انرژی و…)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"alternative approaches to learning","translation":"رویکردهای جایگزین برای یادگیری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630666.mp3"},{"sentence":"Have you any alternative suggestions ?","translation":"آیا پیشنهاد جایگزینی دارید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630667.mp3"},{"sentence":"An alternative route is along the Via Unione.","translation":"یک مسیر جایگزین در امتداد Via Unione است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630671.mp3"}]'::jsonb,3),
('8f4b0f74-a0e2-5b0b-a4d1-1d6242eb081d','f927cf96-5f40-57db-a6f0-effdd2b58b0e',2,null,null,'spoken & written','deliberately different from what is usual , expected, or traditional',null,null,'به طور عمدی متفاوت از آنچه معمول، مورد انتظار یا سنتی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tucson’s alternative radio station","translation":"ایستگاه رادیویی جایگزین توسان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630677.mp3"},{"sentence":"sources of alternative energy (= energy produced by the sun, wind etc rather than by gas, coal etc )","translation":"منابع انرژی جایگزین (= انرژی تولید شده توسط خورشید، باد و غیره به جای گاز، زغال سنگ و غیره)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630680.mp3"},{"sentence":"tolerance of alternative lifestyles","translation":"تحمل سبک زندگی جایگزین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000937836.mp3"},{"sentence":"Acupuncture is widely used by practitioners of alternative medicine.","translation":"طب سوزنی به طور گسترده توسط پزشکان طب جایگزین استفاده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630687.mp3"}]'::jsonb,4),
('44f2c727-fdc8-5ec8-aeed-cc1e8dd8ea8c','adceb9c7-438c-50e4-bb0a-607b07e3acb9',1,null,null,'spoken & written','something you can choose to do or use instead of something else',null,null,'گزینه، راه دیگر، بدیل','{}'::text[],'{}'::text[],array['a good/attractive alternative If you don’t want curtains, blinds are a good alternative.','a possible/acceptable/satisfactory alternative I’m busy tomorrow but Wednesday is a possible alternative.','a real/serious alternative Co-operation offers the only real alternative.','a viable alternative (= that can work as successfully ) Hydrogen offers a viable alternative to petrol and diesel.','a practical alternative This treatment represents a practical alternative to surgery.','a cheap alternative A take-away is a cheap alternative to eating out.','a safe alternative Will there ever be a safe alternative to nuclear power?','a healthy alternative Low-fat biscuits are a healthy alternative to cake.','have an alternative You have a few alternatives to choose from.','offer/provide an alternative If your first choice is not available, we always have alternatives to offer.','suggest an alternative Do you have an alternative you can suggest?','seek an alternative People are seeking alternatives to meat-based dishes.','find an alternative The program is directed to finding alternatives to oil and natural gas.','have no/little alternative (but to do something) He had no alternative but to resign.','leave somebody with no alternative (but to do something) I was left with no alternative but to seek legal advice.']::text[],'[{"sentence":"Is there a viable alternative to the present system?","translation":"آیا جایگزین مناسبی برای سیستم فعلی وجود دارد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000937856.mp3"},{"sentence":"If payment is not received, legal action will be our only alternative .","translation":"در صورت عدم دریافت وجه، اقدام قانونی تنها جایگزین ما خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630694.mp3"},{"sentence":"I had no alternative but to report him to the police.","translation":"چاره ای جز گزارش دادن او به پلیس نداشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630698.mp3"},{"sentence":"He quickly assessed the alternatives open to him.","translation":"او به سرعت گزینه های موجود برای او را ارزیابی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00043.mp3"}]'::jsonb,4),
('5bf39f2a-620c-531e-83fa-da90df37244a','a84a82cc-b613-55b2-acae-1eb588c41787',1,'written request','درخواست کتبی','spoken & written','a formal , usually written, request for something such as a job, place at university , or permission to do something','[ countable, uncountable ]',null,'درخواست (کتبی)؛ درخواست‌نامه؛ نرم‌افزار کاربردی','{}'::text[],'{}'::text[],array['a job application He''s made twenty-three job applications and had five interviews.','a planning application (= an official request for permission to build something ) We have lodged a planning application for a housing development on the site.','a formal application (= made officially ) Turkey has made a formal application to join the European Union.','an application form Simply fill in the application form and return it to your bank.','a letter of application The purpose of your letter of application is to get an interview.','make an application Candidates are advised to make an early application to the university.','fill out/fill in an application (= write all the necessary information on it ) I would like to fill out an application for the position. You can fill in the application form online.','put in/submit an application The company has submitted a planning application.','consider an application (= think carefully about it before making a decision ) All applications will be considered on their own merits.','grant/approve an application (= give permission to do or have something ) What are the reasons for not granting this application?','refuse/reject/turn down an application (= say no to an application ) Their planning application was rejected because of a lack of parking facilities.','process an application (= officially deal with it ) Your application for British citizenship will be processed by the Immigration Service.','accept an application The college refused to accept my application.','withdraw your application The company withdrew its application to build the bridge.']::text[],'[{"sentence":"an application for a grant","translation":"درخواست برای کمک هزینه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000984446.mp3"},{"sentence":"The university welcomes applications from overseas students.","translation":"این دانشگاه از درخواست های دانشجویان خارج از کشور استقبال می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672347.mp3"},{"sentence":"We receive hundreds of job applications each year.","translation":"ما هر سال صدها درخواست شغلی دریافت می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913318.mp3"},{"sentence":"I filled in the application form and sent it off.","translation":"من فرم درخواست را پر کردم و فرستادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672348.mp3"},{"sentence":"You have to submit your application before the end of the month.","translation":"شما باید قبل از پایان ماه درخواست خود را ارسال کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941405.mp3"},{"sentence":"I’ve put in an application for a transfer.","translation":"من یک درخواست برای انتقال گذاشته ام.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913314.mp3"},{"sentence":"He received a letter saying that his application had been rejected .","translation":"او نامه ای دریافت کرد که در آن درخواست او رد شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941411.mp3"},{"sentence":"It can take a long time for your visa application to be processed .","translation":"ممکن است زمان زیادی طول بکشد تا درخواست ویزای شما بررسی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941417.mp3"},{"sentence":"The Council is currently reviewing the way it deals with planning applications .","translation":"شورا در حال حاضر در حال بررسی نحوه برخورد با برنامه های برنامه ریزی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941423.mp3"},{"sentence":"Thank you for your letter of application , which we received yesterday.","translation":"از نامه درخواست شما که دیروز دریافت کردیم سپاسگزاریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941427.mp3"}]'::jsonb,10),
('cb2e0ec1-29a1-5cc5-b12b-64697b3b6452','a84a82cc-b613-55b2-acae-1eb588c41787',2,'practical use','استفاده عملی','spoken & written','the practical purpose for which a machine , idea etc can be used, or a situation when this is used','[ countable, uncountable ]',null,'هدف عملی که یک ماشین، ایده و غیره می تواند برای آن استفاده شود، یا موقعیتی که از آن استفاده می شود','{}'::text[],'{}'::text[],array['a job application He''s made twenty-three job applications and had five interviews.','a planning application (= an official request for permission to build something ) We have lodged a planning application for a housing development on the site.','a formal application (= made officially ) Turkey has made a formal application to join the European Union.','an application form Simply fill in the application form and return it to your bank.','a letter of application The purpose of your letter of application is to get an interview.','make an application Candidates are advised to make an early application to the university.','fill out/fill in an application (= write all the necessary information on it ) I would like to fill out an application for the position. You can fill in the application form online.','put in/submit an application The company has submitted a planning application.','consider an application (= think carefully about it before making a decision ) All applications will be considered on their own merits.','grant/approve an application (= give permission to do or have something ) What are the reasons for not granting this application?','refuse/reject/turn down an application (= say no to an application ) Their planning application was rejected because of a lack of parking facilities.','process an application (= officially deal with it ) Your application for British citizenship will be processed by the Immigration Service.','accept an application The college refused to accept my application.','withdraw your application The company withdrew its application to build the bridge.']::text[],'[{"sentence":"the applications of genetic engineering in agriculture","translation":"کاربردهای مهندسی ژنتیک در کشاورزی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672356.mp3"},{"sentence":"The research has many practical applications .","translation":"این تحقیق کاربردهای عملی زیادی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672357.mp3"}]'::jsonb,2),
('31d58fb9-5510-5822-8639-c12d2deed7e7','a84a82cc-b613-55b2-acae-1eb588c41787',3,'computers','کامپیوترها','spoken & written','a piece of computer software which does a particular job','[ countable ]',null,'یک نرم افزار کامپیوتری که کار خاصی را انجام می دهد','{}'::text[],'{}'::text[],array['a job application He''s made twenty-three job applications and had five interviews.','a planning application (= an official request for permission to build something ) We have lodged a planning application for a housing development on the site.','a formal application (= made officially ) Turkey has made a formal application to join the European Union.','an application form Simply fill in the application form and return it to your bank.','a letter of application The purpose of your letter of application is to get an interview.','make an application Candidates are advised to make an early application to the university.','fill out/fill in an application (= write all the necessary information on it ) I would like to fill out an application for the position. You can fill in the application form online.','put in/submit an application The company has submitted a planning application.','consider an application (= think carefully about it before making a decision ) All applications will be considered on their own merits.','grant/approve an application (= give permission to do or have something ) What are the reasons for not granting this application?','refuse/reject/turn down an application (= say no to an application ) Their planning application was rejected because of a lack of parking facilities.','process an application (= officially deal with it ) Your application for British citizenship will be processed by the Immigration Service.','accept an application The college refused to accept my application.','withdraw your application The company withdrew its application to build the bridge.']::text[],'[{"sentence":"We received training on a number of spreadsheet and database applications.","translation":"ما در مورد تعدادی از برنامه های کاربردی صفحه گسترده و پایگاه داده آموزش دریافت کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000984491.mp3"}]'::jsonb,1),
('69fa862f-f062-5119-adf8-ad57067cd85a','a84a82cc-b613-55b2-acae-1eb588c41787',4,'paint/liquid','رنگ / مایع','spoken & written','when you put something such as paint , liquid , medicine etc onto a surface','[ countable, uncountable ]',null,'وقتی چیزی مانند رنگ، مایع، دارو و غیره را روی یک سطح قرار می دهید','{}'::text[],'{}'::text[],array['a job application He''s made twenty-three job applications and had five interviews.','a planning application (= an official request for permission to build something ) We have lodged a planning application for a housing development on the site.','a formal application (= made officially ) Turkey has made a formal application to join the European Union.','an application form Simply fill in the application form and return it to your bank.','a letter of application The purpose of your letter of application is to get an interview.','make an application Candidates are advised to make an early application to the university.','fill out/fill in an application (= write all the necessary information on it ) I would like to fill out an application for the position. You can fill in the application form online.','put in/submit an application The company has submitted a planning application.','consider an application (= think carefully about it before making a decision ) All applications will be considered on their own merits.','grant/approve an application (= give permission to do or have something ) What are the reasons for not granting this application?','refuse/reject/turn down an application (= say no to an application ) Their planning application was rejected because of a lack of parking facilities.','process an application (= officially deal with it ) Your application for British citizenship will be processed by the Immigration Service.','accept an application The college refused to accept my application.','withdraw your application The company withdrew its application to build the bridge.']::text[],'[{"sentence":"The application of fertilizer increased the size of the plants.","translation":"استفاده از کود باعث افزایش سایز گیاهان شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000984475.mp3"}]'::jsonb,1),
('7448a4e4-fe47-5daa-bced-ff3f0e991ba6','a84a82cc-b613-55b2-acae-1eb588c41787',5,'effort','تلاش','spoken & written','attention or effort over a long period of time','[ uncountable ]',null,'توجه یا تلاش در مدت زمان طولانی','{}'::text[],'{}'::text[],array['a job application He''s made twenty-three job applications and had five interviews.','a planning application (= an official request for permission to build something ) We have lodged a planning application for a housing development on the site.','a formal application (= made officially ) Turkey has made a formal application to join the European Union.','an application form Simply fill in the application form and return it to your bank.','a letter of application The purpose of your letter of application is to get an interview.','make an application Candidates are advised to make an early application to the university.','fill out/fill in an application (= write all the necessary information on it ) I would like to fill out an application for the position. You can fill in the application form online.','put in/submit an application The company has submitted a planning application.','consider an application (= think carefully about it before making a decision ) All applications will be considered on their own merits.','grant/approve an application (= give permission to do or have something ) What are the reasons for not granting this application?','refuse/reject/turn down an application (= say no to an application ) Their planning application was rejected because of a lack of parking facilities.','process an application (= officially deal with it ) Your application for British citizenship will be processed by the Immigration Service.','accept an application The college refused to accept my application.','withdraw your application The company withdrew its application to build the bridge.']::text[],'[{"sentence":"Making your new business successful requires luck, patience, and application.","translation":"موفقیت در کسب و کار جدید نیاز به شانس، صبر و کاربرد دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000984482.mp3"}]'::jsonb,1),
('e8105d9f-6585-5166-b402-119d3fd07e92','a5f2dde3-4998-5bc8-827a-aabd5325da81',1,null,null,'spoken & written','an arrangement for a meeting at an agreed time and place, for a particular purpose','[ countable ]',null,'قرار ملاقات؛ منصب، انتصاب','{}'::text[],'{}'::text[],array['have an appointment She has an appointment with the dentist at 5 o''clock.','make/arrange an appointment Can you phone the hairdresser and make an appointment?','book an appointment British English , schedule an appointment American English (= make an appointment ) Have you booked another appointment at the clinic? I’ve scheduled your appointment for 9.30.','cancel an appointment He had to cancel all his afternoon appointments.','get an appointment (= succeed in arranging one ) It’s difficult to get an appointment on Monday morning.','miss an appointment (= not go to an appointment you have arranged ) The train was late so I missed my appointment.','keep an appointment (= go to an appointment that you have arranged ) Please let us know if you cannot keep your appointment.','a hospital appointment British English My hospital appointment lasted half an hour.','a doctor’s appointment ( also an appointment at the doctor’s ) What time is your doctor’s appointment? I have an appointment at the doctor’s this morning.','an urgent appointment I can’t talk now – I have an urgent appointment to get to.','a dentist’s/dental appointment She has a dental appointment, so she won’t be in until later.','a medical appointment Children sometimes miss school because of medical appointments.','a business appointment Dennis had an early-morning business appointment with a client.','a hair appointment (= to have your hair cut ) I’d like to make a hair appointment for next week.','a morning/afternoon appointment I asked for a morning appointment.']::text[],'[{"sentence":"I’d like to make an appointment to see the doctor.","translation":"من می خواهم برای دیدن دکتر یک قرار ملاقات بگذارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000087.mp3"},{"sentence":"He has an appointment with a client at 10.30.","translation":"او ساعت 10.30 با یک مشتری قرار دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000088.mp3"},{"sentence":"All consultations are by appointment only .","translation":"کلیه مشاوره ها فقط با تعیین وقت قبلی می باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672034.mp3"}]'::jsonb,3),
('251127c8-4c4d-578b-81df-8aca55658365','a5f2dde3-4998-5bc8-827a-aabd5325da81',2,null,null,'spoken & written','when someone is chosen for a position or job','[ countable, uncountable ]',null,'زمانی که شخصی برای یک موقعیت یا شغل انتخاب می شود','{}'::text[],'{}'::text[],array['have an appointment She has an appointment with the dentist at 5 o''clock.','make/arrange an appointment Can you phone the hairdresser and make an appointment?','book an appointment British English , schedule an appointment American English (= make an appointment ) Have you booked another appointment at the clinic? I’ve scheduled your appointment for 9.30.','cancel an appointment He had to cancel all his afternoon appointments.','get an appointment (= succeed in arranging one ) It’s difficult to get an appointment on Monday morning.','miss an appointment (= not go to an appointment you have arranged ) The train was late so I missed my appointment.','keep an appointment (= go to an appointment that you have arranged ) Please let us know if you cannot keep your appointment.','a hospital appointment British English My hospital appointment lasted half an hour.','a doctor’s appointment ( also an appointment at the doctor’s ) What time is your doctor’s appointment? I have an appointment at the doctor’s this morning.','an urgent appointment I can’t talk now – I have an urgent appointment to get to.','a dentist’s/dental appointment She has a dental appointment, so she won’t be in until later.','a medical appointment Children sometimes miss school because of medical appointments.','a business appointment Dennis had an early-morning business appointment with a client.','a hair appointment (= to have your hair cut ) I’d like to make a hair appointment for next week.','a morning/afternoon appointment I asked for a morning appointment.']::text[],'[{"sentence":"Other changes included the appointment of a new Foreign Minister.","translation":"از دیگر تغییرات می توان به انتصاب وزیر خارجه جدید اشاره کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672041.mp3"},{"sentence":"They congratulated him on his appointment as chairman.","translation":"آنها انتصاب او به عنوان رئیس را تبریک گفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672044.mp3"}]'::jsonb,2),
('6c33796f-2e7b-5438-880d-ccb79d2e868f','a5f2dde3-4998-5bc8-827a-aabd5325da81',3,null,null,'spoken & written','a job or position, usually involving some responsibility','[ countable ]',null,'شغل یا موقعیتی که معمولاً شامل مسئولیتی است','{}'::text[],'{}'::text[],array['have an appointment She has an appointment with the dentist at 5 o''clock.','make/arrange an appointment Can you phone the hairdresser and make an appointment?','book an appointment British English , schedule an appointment American English (= make an appointment ) Have you booked another appointment at the clinic? I’ve scheduled your appointment for 9.30.','cancel an appointment He had to cancel all his afternoon appointments.','get an appointment (= succeed in arranging one ) It’s difficult to get an appointment on Monday morning.','miss an appointment (= not go to an appointment you have arranged ) The train was late so I missed my appointment.','keep an appointment (= go to an appointment that you have arranged ) Please let us know if you cannot keep your appointment.','a hospital appointment British English My hospital appointment lasted half an hour.','a doctor’s appointment ( also an appointment at the doctor’s ) What time is your doctor’s appointment? I have an appointment at the doctor’s this morning.','an urgent appointment I can’t talk now – I have an urgent appointment to get to.','a dentist’s/dental appointment She has a dental appointment, so she won’t be in until later.','a medical appointment Children sometimes miss school because of medical appointments.','a business appointment Dennis had an early-morning business appointment with a client.','a hair appointment (= to have your hair cut ) I’d like to make a hair appointment for next week.','a morning/afternoon appointment I asked for a morning appointment.']::text[],'[{"sentence":"He has taken up an appointment as Professor of Chemistry.","translation":"او به عنوان استاد شیمی انتخاب شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000944810.mp3"}]'::jsonb,1),
('839cf1d8-3afb-5381-a2a1-02799866dd29','a5f2dde3-4998-5bc8-827a-aabd5325da81',4,null,null,'spoken & written',null,null,'by appointment to the Queen','قرار ملاقات؛ منصب، انتصاب','{}'::text[],'{}'::text[],array['have an appointment She has an appointment with the dentist at 5 o''clock.','make/arrange an appointment Can you phone the hairdresser and make an appointment?','book an appointment British English , schedule an appointment American English (= make an appointment ) Have you booked another appointment at the clinic? I’ve scheduled your appointment for 9.30.','cancel an appointment He had to cancel all his afternoon appointments.','get an appointment (= succeed in arranging one ) It’s difficult to get an appointment on Monday morning.','miss an appointment (= not go to an appointment you have arranged ) The train was late so I missed my appointment.','keep an appointment (= go to an appointment that you have arranged ) Please let us know if you cannot keep your appointment.','a hospital appointment British English My hospital appointment lasted half an hour.','a doctor’s appointment ( also an appointment at the doctor’s ) What time is your doctor’s appointment? I have an appointment at the doctor’s this morning.','an urgent appointment I can’t talk now – I have an urgent appointment to get to.','a dentist’s/dental appointment She has a dental appointment, so she won’t be in until later.','a medical appointment Children sometimes miss school because of medical appointments.','a business appointment Dennis had an early-morning business appointment with a client.','a hair appointment (= to have your hair cut ) I’d like to make a hair appointment for next week.','a morning/afternoon appointment I asked for a morning appointment.']::text[],'[]'::jsonb,0),
('0441f9d7-974d-544c-9d09-9d16e855ea05','a9b153a3-58b7-51c8-a7c0-a1873b4c1007',1,null,null,'spoken & written','correct or suitable for a particular time, situation, or purpose',null,null,'مناسب، بجا','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"clothes appropriate for a job interview","translation":"لباس مناسب برای مصاحبه شغلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945696.mp3"},{"sentence":"an education system which is more appropriate to the needs of the students","translation":"یک سیستم آموزشی که بیشتر با نیازهای دانش آموزان سازگار باشد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945699.mp3"},{"sentence":"It would not be appropriate for me to discuss that now.","translation":"برای من مناسب نیست که اکنون در مورد آن بحث کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672158.mp3"},{"sentence":"It seemed somehow appropriate that we should begin our journey here.","translation":"به نظر می رسید که ما باید سفر خود را از اینجا شروع کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941283.mp3"},{"sentence":"I didn’t feel that this was an appropriate time to mention the subject of money.","translation":"من احساس نمی کردم که این زمان مناسبی برای ذکر موضوع پول است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672161.mp3"},{"sentence":"I thought his remark was highly appropriate, given the circumstances.","translation":"به نظرم اظهارات ایشان با توجه به شرایط بسیار مناسب بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941286.mp3"},{"sentence":"The timing of the announcement was particularly appropriate .","translation":"زمان اعلام به ویژه مناسب بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913415.mp3"},{"sentence":"Where appropriate , I delegate as much work as possible.","translation":"در صورت لزوم، من تا آنجا که ممکن است کار را محول می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913419.mp3"},{"sentence":"Mark box 1 or 2, as appropriate .","translation":"در صورت لزوم، کادر 1 یا 2 را علامت بزنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672164.mp3"},{"sentence":"I can assure you that appropriate action will be taken.","translation":"من می توانم به شما اطمینان دهم که اقدامات لازم انجام خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913422.mp3"}]'::jsonb,10),
('4e4acaf2-f721-5630-aaf0-6a68520a685c','d247fa09-4635-5765-aaf3-e5ff3363d9bc',1,null,null,'spoken & written','to take something for yourself when you do not have the right to do this',null,null,'وقتی حق این کار را ندارید برای خود چیزی بردارید',array['steal']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He is suspected of appropriating government funds.","translation":"او مظنون به تصاحب وجوه دولتی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945722.mp3"}]'::jsonb,1),
('49c523fd-93c8-5d9e-a6d1-a585d09f0244','d247fa09-4635-5765-aaf3-e5ff3363d9bc',2,null,null,'spoken & written','to take something, especially money, to use for a particular purpose',null,null,'گرفتن چیزی، به ویژه پول، برای استفاده برای یک هدف خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Congress appropriated $5 million for International Women’s Year.","translation":"کنگره 5 میلیون دلار برای سال جهانی زن اختصاص داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000089.mp3"}]'::jsonb,1),
('91795501-3971-52d1-901d-ca4a5655e003','5ff9a811-6a60-5050-89f8-38612c938153',1,null,null,'spoken & written','an approximate number, amount, or time is close to the exact number, amount etc, but could be a little bit more or less than it',null,null,'تقریبی، حدودی',array['rough']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"What is the approximate number of students in each class?","translation":"تعداد دانش آموزان هر کلاس به طور تقریبی چقدر است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000947406.mp3"},{"sentence":"These percentages are only approximate.","translation":"این درصدها فقط تقریبی هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672224.mp3"},{"sentence":"Can you give me a rough idea of how much it would cost?","translation":"می توانید یک ایده کلی از هزینه آن به من بدهید؟","audio_url":null}]'::jsonb,3),
('beb88f79-aeb3-5e99-b083-68945d3da5d4','4170c08b-e986-5f67-81db-19898cb9459c',1,null,null,'spoken & written','to be close to a particular number',null,null,'نزدیک بودن به یک عدد خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This figure approximates to a quarter of the UK’s annual consumption.","translation":"این رقم تقریباً یک چهارم مصرف سالانه انگلستان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000947425.mp3"}]'::jsonb,1),
('4bff059c-e45e-527f-b406-8e3bd5da58c7','4170c08b-e986-5f67-81db-19898cb9459c',2,null,null,'spoken & written','to be similar to but not exactly the same as something',null,null,'شبیه بودن اما نه دقیقاً مشابه چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Your story only approximates to the real facts.","translation":"داستان شما فقط به حقایق واقعی تقریب دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000947431.mp3"}]'::jsonb,1),
('dfd42ad2-b148-5a55-a3d9-ae90ba206774','91d9c2c5-fbc4-50db-8f24-381ead9ea5a8',1,'plan','برنامه ریزی کنید','spoken & written','plans and preparations that you must make so that something can happen','[ countable usually plural ]',null,'ترتیب، قرارداد؛ چیدمان، آراستگی','{}'::text[],'{}'::text[],array['make arrangements You are advised to make travel arrangements well in advance.','discuss the arrangements We need to discuss the wedding arrangements.','finalize the arrangements I’m meeting him tomorrow to finalize the arrangements.','upset the arrangements (= cause problems which spoil the arrangements ) I don’t want to upset your arrangements.','alternative arrangements If the flight is cancelled you’ll have to make alternative arrangements.','special arrangements (= particular preparations other than those usually made ) Please inform us if any guests have disabilities or need any special arrangements.','security arrangements He was in charge of security arrangements for the president’s visit.','financial arrangements As treasurer, you’re responsible for all the financial arrangements.','travel arrangements I’ll make my own travel arrangements.','holiday arrangements British English We don’t have any holiday arrangements yet.','seating/sleeping arrangements (= plans for where people will sit/sleep ) What are the seating arrangements for dinner?']::text[],'[{"sentence":"Have you made all your travel arrangements?","translation":"آیا تمام برنامه های سفر خود را انجام داده اید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000100.mp3"},{"sentence":"I’ve agreed to help with arrangements for the party.","translation":"من موافقت کرده ام که در ترتیبات مهمانی کمک کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949877.mp3"},{"sentence":"The family made arrangements for his body to be flown back.","translation":"خانواده مقدمات انتقال جسد او را فراهم کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000101.mp3"}]'::jsonb,3),
('ef87d5c5-c55e-54f9-9f4e-360c33f04db7','91d9c2c5-fbc4-50db-8f24-381ead9ea5a8',2,'agreement','توافق نامه','spoken & written','something that has been organized or agreed on','[ countable, uncountable ]',null,'چیزی که در مورد آن سازماندهی یا توافق شده است',array['agreement']::text[],'{}'::text[],array['make arrangements You are advised to make travel arrangements well in advance.','discuss the arrangements We need to discuss the wedding arrangements.','finalize the arrangements I’m meeting him tomorrow to finalize the arrangements.','upset the arrangements (= cause problems which spoil the arrangements ) I don’t want to upset your arrangements.','alternative arrangements If the flight is cancelled you’ll have to make alternative arrangements.','special arrangements (= particular preparations other than those usually made ) Please inform us if any guests have disabilities or need any special arrangements.','security arrangements He was in charge of security arrangements for the president’s visit.','financial arrangements As treasurer, you’re responsible for all the financial arrangements.','travel arrangements I’ll make my own travel arrangements.','holiday arrangements British English We don’t have any holiday arrangements yet.','seating/sleeping arrangements (= plans for where people will sit/sleep ) What are the seating arrangements for dinner?']::text[],'[{"sentence":"An arrangement between the two couples ensured there was always someone to look after the children.","translation":"هماهنگی بین دو زوج اطمینان حاصل کرد که همیشه کسی برای مراقبت از کودکان وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664035.mp3"},{"sentence":"The school has an arrangement with local businesses.","translation":"مدرسه با مشاغل محلی هماهنگی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664038.mp3"},{"sentence":"Maxine cancelled our arrangement to meet.","translation":"ماکسین قرار ملاقات ما را لغو کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664041.mp3"},{"sentence":"It would usually cost $500, but I’m sure we can come to some kind of arrangement.","translation":"معمولاً 500 دلار هزینه دارد، اما من مطمئن هستم که می‌توانیم به نوعی هماهنگی کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000949893.mp3"},{"sentence":"Pets are permitted at the resort by prior arrangement .","translation":"حیوانات خانگی با هماهنگی قبلی در استراحتگاه مجاز هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664042.mp3"}]'::jsonb,5),
('7fc1cc9b-f70c-5c59-a507-764e73cbbf73','91d9c2c5-fbc4-50db-8f24-381ead9ea5a8',3,'way something is organized','نحوه سازماندهی چیزی','spoken & written','the way in which something is organized','[ countable usually plural ]',null,'روشی که در آن چیزی سازماندهی می شود','{}'::text[],'{}'::text[],array['make arrangements You are advised to make travel arrangements well in advance.','discuss the arrangements We need to discuss the wedding arrangements.','finalize the arrangements I’m meeting him tomorrow to finalize the arrangements.','upset the arrangements (= cause problems which spoil the arrangements ) I don’t want to upset your arrangements.','alternative arrangements If the flight is cancelled you’ll have to make alternative arrangements.','special arrangements (= particular preparations other than those usually made ) Please inform us if any guests have disabilities or need any special arrangements.','security arrangements He was in charge of security arrangements for the president’s visit.','financial arrangements As treasurer, you’re responsible for all the financial arrangements.','travel arrangements I’ll make my own travel arrangements.','holiday arrangements British English We don’t have any holiday arrangements yet.','seating/sleeping arrangements (= plans for where people will sit/sleep ) What are the seating arrangements for dinner?']::text[],'[{"sentence":"The airport is currently reviewing its security arrangements .","translation":"فرودگاه در حال حاضر در حال بررسی ترتیبات امنیتی خود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664050.mp3"},{"sentence":"domestic arrangements","translation":"ترتیبات داخلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664051.mp3"}]'::jsonb,2),
